from datetime import date
from collections import defaultdict


class Loyalty:
    def __init__(self) -> None:
        self._balances: dict[str, int] = defaultdict(int)

    def purchase(self, customer: str, amount: float, day: date) -> int:
        """Record a purchase; returns the number of points earned."""
        if amount <= 0:
            raise ValueError("Purchase amount must be greater than zero.")
        points = int(amount // 10)
        self._balances[customer] += points
        return points

    def balance(self, customer: str, day: date) -> int:
        """Points the customer can spend on the given day."""
        return self._balances[customer]

    def redeem(self, customer: str, points: int, day: date) -> None:
        """Redeem points for a customer."""
        if points <= 0 or points % 100 != 0:
            raise ValueError("Points can only be redeemed in positive multiples of 100.")
        if points > self._balances[customer]:
            raise ValueError("Cannot redeem more points than the available balance.")
        self._balances[customer] -= points
